<script setup lang="ts">
const {t}=useI18n(),route=useRoute(),router=useRouter(),warehouse=useWarehouseStore(),staff=useStaffStore(),{bizErrorMessage}=useBizError()
const data=ref<PaginationData|null>(null),loading=ref(false),error=ref(''),keyword=ref(String(route.query.keyword||'')),counts=ref<Record<string,number>>({})
const ready=ref(false)
const allowed=(...permissions:string[])=>ready.value&&staff.hasPermission(...permissions)
const carriers=ref<{value:number;label:string}[]>([])
const filterError=ref('')
let carrierGeneration=0
const loadCarriers=async()=>{
 const seq=++carrierGeneration
 carriers.value=[];filterError.value=''
 if(!allowed('carrier_read'))return
 const options:{value:number;label:string}[]=[]
 for(const is_active of [true,false]){
  let optionPage=1
  while(true){
   const result=await httpRequest<PaginationData>('/api/warehouse/carrier/',{params:{is_active,page:optionPage,per_page:100},onError:e=>{if(seq===carrierGeneration)filterError.value=bizErrorMessage(e)}})
   if(seq!==carrierGeneration||!result)return
   options.push(...result.items.map((row:any)=>({value:row.id,label:row.name})))
   if(optionPage>=result.pages)break
   optionPage++
  }
 }
 carriers.value=options
}
const statuses=['all','preparing','awaiting_waybill','awaiting_number','awaiting_pickup','awaiting_handover','in_transit','exception','delivered','closed'],active=computed(()=>String(route.query.shipping_stage||'all')),page=computed(()=>Number(route.query.page)||1)
const tabs=computed(()=>statuses.map(key=>({key,label:key==='all'?t('common.status.all'):t('shipping.stage.'+key),count:counts.value[key],attention:key.startsWith('awaiting_'),error:key==='exception'})))
const go=(patch:Record<string,any>)=>{const query:Record<string,any>={...route.query,page:1,...patch};for(const key of Object.keys(query))if(query[key]===''||query[key]==='all'||query[key]==null)delete query[key];router.push({query})}
let previousWarehouseScope=String(warehouse.currentWarehouse?.id??useCookie('warehouse_id').value??'')
let generation=0
const load=async()=>{if(!ready.value)return;const seq=++generation;loading.value=true;error.value='';data.value=null;counts.value={};const headers=warehouseHeaders(warehouse.currentWarehouse?.id),base={...route.query,warehouse_id:warehouse.currentWarehouse?.id};const results=await Promise.all([httpRequest<PaginationData>('/api/warehouse/delivery/',{params:{...base,page:page.value,per_page:20},headers,onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}}),...statuses.map(status=>httpRequest<PaginationData>('/api/warehouse/delivery/',{params:{...base,shipping_stage:status==='all'?undefined:status,page:1,per_page:1},headers,onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}}))]);if(seq!==generation)return;data.value=results[0]||null;statuses.forEach((key,i)=>{if(results[i+1])counts.value[key]=results[i+1]!.total});loading.value=false}
const initialize=async()=>{const seq=++generation;ready.value=false;loading.value=true;error.value='';data.value=null;counts.value={};carriers.value=[];carrierGeneration++;const current=await staff.getCurrentStaffInfo();if(seq!==generation)return;if(!current){error.value=t('common.permissions-unavailable');loading.value=false;return}await warehouse.fetchWarehouses();if(seq!==generation)return;ready.value=true;await Promise.all([load(),loadCarriers()])}
const columns=computed(()=>[{key:'task',label:t('delivery.entity')},{key:'recipient_name',label:t('nav.recipient')},{key:'carrier',label:t('nav.carrier')+' · '+t('common.fields.tracking-number')},{key:'pickup',label:t('carrier.methods.pickup')},{key:'expected_shipping_date',label:t('dn.fields.scheduled-date')},{key:'status',label:t('shipping.stage-label')},{key:'next',label:t('operations.ui.next'),align:'right' as const}])
watch(()=>route.query,()=>{keyword.value=String(route.query.keyword||'');load()});watch(()=>warehouse.currentWarehouse?.id,id=>{const scope=String(id??'');const changed=scope!==previousWarehouseScope;previousWarehouseScope=scope;if(changed&&route.query.page&&Number(route.query.page)!==1)go({page:1});else load()});onMounted(initialize);onBeforeUnmount(()=>{generation++;carrierGeneration++})
useHead({title:()=>t('nav.delivery')})
</script>
<template><div class="w-delivery-list w-scope"><header><div><h1>{{t('nav.delivery')}}</h1><span>{{warehouse.currentWarehouse?.name||t('common.all-warehouse')}} · {{data?.total??'—'}}</span></div><WButton v-if="allowed('delivery_read')" to="/delivery/pickup">{{t('delivery.pickup.nav-button')}}</WButton></header><WCard flush><WTabs :label="t('common.fields.status')" inset :items="tabs" :model-value="active" @update:model-value="value=>go({shipping_stage:value})"/><form class="filters" @submit.prevent="go({keyword:keyword.trim()})"><WInput v-model="keyword" type="search" :placeholder="t('delivery.form.placeholders.search')" :aria-label="t('common.search')"><template #prefix><WIcon name="search" :size="16"/></template></WInput><WButton type="submit">{{t('common.search')}}</WButton><WFilterSelect :model-value="String(route.query.status||'')||null" :label="t('common.fields.status')" :options="['pending','in_progress','completed','signed'].map(value=>({value,label:t('common.status.'+value.replaceAll('_','-'))}))" @change="value=>go({status:value})"/><WFilterSelect v-if="allowed('carrier_read')" :model-value="Number(route.query.carrier_id)||null" :options="carriers" :label="t('nav.carrier')" @change="value=>go({carrier_id:value})"/><WInput class="date-filter" type="date" :model-value="String(route.query.expected_shipping_date||'')" :aria-label="t('delivery-list.date-from')" @update:model-value="value=>go({expected_shipping_date:value})"><template #prefix><span class="date-label">{{t('delivery-list.date-from')}}</span></template></WInput></form><WAlert v-if="filterError" tone="block" :title="filterError"><template #actions><WButton @click="loadCarriers">{{t('dn.list.retry')}}</WButton></template></WAlert><WAlert v-if="error" tone="block" :title="error"><template #actions><WButton @click="ready?load():initialize()">{{t('dn.list.retry')}}</WButton></template></WAlert><WTable :rows="data?.items||[]" :columns="columns" :loading="loading" inset><template #cell-task="{row}"><NuxtLink class="w-delivery-name" :to="'/delivery/detail/'+row.id">DEL-{{row.id}}</NuxtLink><NuxtLink v-if="allowed('dn_read')" class="w-delivery-sub" :to="'/dn/detail/'+row.dn_id">DN-{{row.dn_id}}</NuxtLink><small v-else>DN-{{row.dn_id}}</small><small>{{row.order_number}}</small></template><template #cell-recipient_name="{row}"><NuxtLink v-if="allowed('recipient_read')" class="w-delivery-name" :to="'/recipient/detail/'+row.recipient_id">{{row.recipient_name}}</NuxtLink><span v-else>{{row.recipient_name}}</span><small class="address">{{row.shipping_address}}</small></template><template #cell-carrier="{row}">{{row.carrier_name||'—'}}<small>{{row.tracking_number||'—'}}</small></template><template #cell-pickup="{row}"><template v-if="row.pickup_summary?.booking"><span>{{t('delivery.pickup.status.'+row.pickup_summary.booking.status)}}</span><small>{{row.pickup_summary.booking.date}}<br>{{row.pickup_summary.booking.ready_time}}–{{row.pickup_summary.booking.close_time}}</small><small v-if="row.pickup_summary.booking.reason==='cancel_unclear'">{{t('delivery-list.cancel-unclear')}}</small></template><span v-else-if="row.shipping_stage==='awaiting_pickup'">{{t('delivery.pickup.row-status.none')}}</span><span v-else>{{row.pickup_summary?.method?t('carrier.methods.options.pickup.'+row.pickup_summary.method):'—'}}</span></template><template #cell-status="{row}"><WStatus :tone="row.shipping_stage==='exception'?'bad':row.shipping_stage==='delivered'?'ok':row.shipping_stage?.startsWith('awaiting_')?'warn':row.shipping_stage==='in_transit'?'info':'none'">{{row.shipping_stage?t('shipping.stage.'+row.shipping_stage):t('common.status.'+row.status.replaceAll('_','-'))}}</WStatus></template><template #cell-next="{row}"><WButton :to="'/delivery/detail/'+row.id" size="sm">{{t('operations.ui.view')}}</WButton></template></WTable><footer><WPagination :page="page" :page-size="20" :total="data?.total" show-total @update:page="value=>go({page:value})"/></footer></WCard></div></template>
<style scoped>
.w-delivery-list{display:flex;flex-direction:column;gap:16px}header,header>div{display:flex;align-items:center;gap:12px}header{justify-content:space-between;flex-wrap:wrap}h1{font-size:24px;line-height:32px;font-weight:600;margin:0}header span{font-size:13px;color:var(--w-text-2)}.filters{display:flex;flex-wrap:wrap;align-items:center;gap:8px;padding:12px 20px;border-bottom:1px solid var(--w-line)}.filters>.w-input{width:300px;max-width:100%}.filters>.date-filter{width:270px}.date-label{white-space:nowrap;font-size:13px;color:var(--w-text-3)}.w-delivery-list :deep(.w-table){min-width:1100px}.w-delivery-list :deep(.w-table-wrap.is-inset){--w-table-edge:20px}.w-delivery-list :deep(.w-table th){height:auto;padding-top:10px;padding-bottom:8px;line-height:16px}.w-delivery-list :deep(.w-table td){vertical-align:top;padding-top:12px;padding-bottom:12px}.w-delivery-name{display:block;font-size:14px;font-weight:500;line-height:20px;color:var(--w-text-1);text-decoration:none}.w-delivery-sub,small{display:block;font-size:12px;line-height:18px;color:var(--w-text-3);margin-top:4px;text-decoration:none}.address{max-width:220px;white-space:normal}footer{padding:12px 20px;border-top:1px solid var(--w-line)}
</style>
